const userIdHeader = z.uuid();

/** Anything but a UUID in `x-kip-user` counts as no user. */
export function createContext({ req }: { req: Request }): Context {
  const parsed = userIdHeader.safeParse(req.headers.get("x-kip-user"));
  return { userId: parsed.success ? parsed.data : null };
}

